#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_glitchAmount;
uniform float amzp_glitchSpeed;
uniform float amzp_chromaticAmount;
uniform float amzp_chromaticOffset;
uniform float amzp_distortionAmount;
uniform float amzp_barrelAmount;
uniform float amzp_scanlineAmount;
uniform float amzp_scanlineSpeed;
uniform float amzp_vignetteAmount;
uniform float amzp_vignetteIntensity;
uniform float amzp_noiseAmount;
uniform float amzp_noiseScale;
uniform float amzp_saturation;
uniform float amzp_contrast;


        float onOff(float a, float b, float c) {
            return step(c, sin(time * amzp_glitchSpeed + a * cos(time * amzp_glitchSpeed * b)));
        }

        float ramp(float y, float start, float end) {
            float inside = step(start, y) - step(end, y);
            float fact = (y - start) / (end - start) * inside;
            return (1.0 - fact) * inside;
        }

        float4 getVideo(float2 uv) {
            float2 look = uv;
            float window = 1.0 / (1.0 + 20.0 * (look.y - mod(time * amzp_glitchSpeed / 4.0, 1.0)) * (look.y - mod(time * amzp_glitchSpeed / 4.0, 1.0)));
            look.x = look.x + (sin(look.y * 10.0 + time * amzp_glitchSpeed) / 50.0 * onOff(4.0, 4.0, 0.3) * (1.0 + cos(time * amzp_glitchSpeed * 80.0)) * window) * (0.1 * 2.0);
            float vShift = 0.4 * onOff(2.0, 3.0, 0.9) * (sin(time * amzp_glitchSpeed) * sin(time * amzp_glitchSpeed * 20.0) + (0.5 + 0.1 * sin(time * amzp_glitchSpeed * 200.0) * cos(time * amzp_glitchSpeed)));
            look.y = mod(look.y + vShift * 0.1, 1.0);

            float4 video = amzTexture(0, look);
            return video;
        }

        float2 screenDistort(float2 uv) {
            uv = (uv - 0.5) * 2.0;
            uv *= 1.1 * amzp_distortionAmount;
            uv.x *= 1.0 + pow((abs(uv.y) / 5.0), 2.0) * amzp_barrelAmount;
            uv.y *= 1.0 + pow((abs(uv.x) / 4.0), 2.0) * amzp_barrelAmount;
            uv = (uv / 2.0) + 0.5;
            uv = uv * 0.92 + 0.04;
            return uv;
        }

        float random(float2 uv) {
            return fract(sin(dot(uv, float2(15.5151, 42.2561))) * 12341.14122 * sin(time * amzp_glitchSpeed * 0.03));
        }

        float noise(float2 uv) {
            float2 i = floor(uv);
            float2 f = fract(uv);

            float a = random(i);
            float b = random(i + float2(1.0, 0.0));
            float c = random(i + float2(0.0, 1.0));
            float d = random(i + float2(1.0));

            float2 u = smoothstep(0.0, 1.0, f);

            return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
        }

        float2 scandistort(float2 uv) {
            float scan1 = clamp(cos(uv.y * 2.0 + time * amzp_glitchSpeed * amzp_scanlineSpeed), 0.0, 1.0);
            float scan2 = clamp(cos(uv.y * 2.0 + time * amzp_glitchSpeed * amzp_scanlineSpeed + 4.0) * 10.0, 0.0, 1.0);
            float amount = scan1 * scan2 * uv.x * amzp_scanlineAmount;
            return uv;
        }

        void amzRender() {
            float2 uv = amzScreenNorm();
            float2 curUV = screenDistort(uv);
            uv = scandistort(curUV);

            float4 video = getVideo(uv);

            float vigAmt = amzp_vignetteIntensity + 0.3 * sin(time * amzp_glitchSpeed + 5.0 * cos(time * amzp_glitchSpeed * 5.0));
            float x = 0.0;


            float offset = amzp_chromaticOffset * amzp_chromaticAmount;
            video.r = getVideo(float2(x + uv.x + offset, uv.y + offset)).x + 0.05;
            video.g = getVideo(float2(x + uv.x + 0.0, uv.y - offset * 2.0)).y + 0.05;
            video.b = getVideo(float2(x + uv.x - offset * 2.0, uv.y + 0.0)).z + 0.05;


            video.r += 0.08 * getVideo(0.75 * float2(x + 0.025, -0.027) + float2(uv.x + offset, uv.y + offset)).x;
            video.g += 0.05 * getVideo(0.75 * float2(x + -0.022, -0.02) + float2(uv.x + 0.0, uv.y - offset * 2.0)).y;
            video.b += 0.08 * getVideo(0.75 * float2(x + -0.02, -0.018) + float2(uv.x - offset * 2.0, uv.y + 0.0)).z;


            video = clamp(video * 0.6 * amzp_contrast + 0.4 * video * video * 1.0 * amzp_saturation, 0.0, 1.0);


            float vignette = (1.0 - vigAmt * (uv.y - 0.5) * (uv.y - 0.5)) * (1.0 - vigAmt * (uv.x - 0.5) * (uv.x - 0.5));
            video *= vignette * amzp_vignetteAmount;


            video = mix(video, float4(noise(uv * amzp_noiseScale)), amzp_noiseAmount);


            if (curUV.x < 0.0 || curUV.x > 1.0 || curUV.y < 0.0 || curUV.y > 1.0) {
                amzOutput = float4(0.0, 0.0, 0.0, 0.0);
            } else {
                amzOutput = video;
            }
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

